/usr/bin/bash -lc "/runtime/node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';

const source = readFileSync('/workspace/src/session.js', 'utf8');
const {DialogResource} = await import("'`data:text/javascript,${encodeURIComponent(source)}`);
const flush = () => Promise.resolve();
class Host {
  constructor(){this.requests=[];this.scheduled=new Map();this.nextId=0;this.published=[];}
  check(token){return new Promise(resolve => this.requests.push({token,resolve}));}
  schedule(callback){const id=++this.nextId;this.scheduled.set(id,callback);return id;}
  cancel(id){this.scheduled.delete(id);}
  publish(state){this.published.push(state);}
  runOne(){const item=this.scheduled.entries().next().value;assert.ok(item,'"'expected scheduled retry');this.scheduled.delete(item[0]);item[1]();}
}

const host = new Host();
const resource = new DialogResource(host, 'package-a');
resource.start();
assert.equal(host.requests.length, 1);
host.requests[0].resolve(false); await flush(); await flush();
assert.equal(resource.snapshot().retryScheduled, true);
assert.equal(host.scheduled.size, 1);
host.runOne();
assert.equal(host.requests.length, 2);
host.requests[1].resolve(false); await flush(); await flush();
assert.equal(host.scheduled.size, 1);
host.runOne();
assert.equal(host.requests.length, 3);
host.requests[2].resolve(true); await flush(); await flush();
assert.deepEqual(resource.snapshot().completed, ['package-a']);
assert.equal(resource.snapshot().retryScheduled, false);
assert.equal(host.scheduled.size, 0);

const lifecycleHost = new Host();
const lifecycle = new DialogResource(lifecycleHost, 'old');
lifecycle.start();
lifecycle.reopen('new');
assert.equal(lifecycleHost.requests.length, 2);
lifecycleHost.requests[0].resolve(false); await flush(); await flush();
assert.equal(lifecycleHost.scheduled.size, 0);
lifecycleHost.requests[1].resolve(false); await flush(); await flush();
assert.equal(lifecycleHost.scheduled.size, 1);
lifecycle.close();
assert.equal(lifecycleHost.scheduled.size, 0);
assert.equal(lifecycle.snapshot().completed.length, 0);
console.log('DialogResource pending retry and lifecycle checks passed');
NODE

